#include <bits/stdc++.h>
using namespace std;
using ll = long long;

const int MAXN = 150;
const int MAX_N = 400;
const ll INF = numeric_limits<ll>::max();

struct Edge {
    int to, rev;
    ll cap;
};

vector<Edge> flowGraph[MAX_N];

void addFlowEdge(int v, int to, ll cap) {
    Edge a{to, (int)flowGraph[to].size(), cap};
    Edge b{v, (int)flowGraph[v].size(), 0};
    flowGraph[v].push_back(a);
    flowGraph[to].push_back(b);
}

ll edmondsKarp(int s, int t) {
    ll total = 0;
    while (true) {
        int parentV[MAX_N];
        int parentE[MAX_N];
        memset(parentV, -1, sizeof(parentV));
        memset(parentE, -1, sizeof(parentE));
        queue<int> q;
        q.push(s);
        parentV[s] = s;
        while (!q.empty() && parentV[t] == -1) {
            int v = q.front();
            q.pop();
            for (int i = 0; i < (int)flowGraph[v].size(); ++i) {
                Edge &e = flowGraph[v][i];
                if (e.cap > 0 && parentV[e.to] == -1) {
                    parentV[e.to] = v;
                    parentE[e.to] = i;
                    q.push(e.to);
                }
            }
        }
        if (parentV[t] == -1) break;

        ll push = INF;
        for (int v = t; v != s; v = parentV[v]) {
            push = min(push, flowGraph[parentV[v]][parentE[v]].cap);
        }
        for (int v = t; v != s; v = parentV[v]) {
            Edge &e = flowGraph[parentV[v]][parentE[v]];
            e.cap -= push;
            flowGraph[v][e.rev].cap += push;
        }
        total += push;
    }
    return total;
}

ll A[MAXN][MAXN], B[MAXN][MAXN], C[MAXN][MAXN], fireT[MAXN][MAXN];
ll seen[MAXN][MAXN], dist[MAXN][MAXN];
int dirI[4] = {-1, 0, 1, 0};
int dirJ[4] = {0, 1, 0, -1};
int idV;
ll answer;
int startI, startJ;
string row;
int n, k;

vector<pair<int,int>> graph[MAXN];
map<int,pair<int,int>> idToCoord;
map<pair<int,int>,int> coordToId;

bool freeCell(int i, int j) {
    if (i < 0 || i >= n || j < 0 || j >= n || A[i][j] == -1 || seen[i][j])
        return false;
    return true;
}

bool canMove(int i, int j, ll d) {
    if (i < 0 || i >= n || j < 0 || j >= n || A[i][j] == -1 || seen[i][j])
        return false;
    if (d + 1 >= fireT[i][j]) {
        if (d + 1 == fireT[i][j]) return C[i][j] == -2;
        return false;
    }
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> k;
    for (int i = 0; i < n; ++i) {
        cin >> row;
        for (int j = 0; j < (int)row.size(); ++j) {
            if (row[j] == 'Y') {
                A[i][j] = -1;
            } else if (row[j] == 'Z') {
                A[i][j] = -1;
                startI = i;
                startJ = j;
            } else {
                A[i][j] = row[j] - '0';
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        cin >> row;
        for (int j = 0; j < (int)row.size(); ++j) {
            if (row[j] == 'Y') {
                B[i][j] = -1;
            } else if (row[j] == 'Z') {
                B[i][j] = -1;
            } else {
                B[i][j] = row[j] - '0';
                if (B[i][j] > 0) C[i][j] = -2;
            }
        }
    }

    idV = 0;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (A[i][j] > 0 || B[i][j] > 0) {
                idToCoord[idV] = {i, j};
                coordToId[{i, j}] = idV++;
            } else {
                coordToId[{i, j}] = -1;
            }
        }
    }

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            fireT[i][j] = 444;

    memset(seen, 0, sizeof(seen));
    queue<pair<int,int>> q;
    q.push({startI, startJ});
    fireT[startI][startJ] = 0;
    while (!q.empty()) {
        auto u = q.front();
        q.pop();
        seen[u.first][u.second] = 1;
        for (int d = 0; d < 4; ++d) {
            int ni = u.first + dirI[d];
            int nj = u.second + dirJ[d];
            if (freeCell(ni, nj)) {
                seen[ni][nj] = 1;
                fireT[ni][nj] = fireT[u.first][u.second] + 1;
                q.push({ni, nj});
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (A[i][j] > 0) {
                for (int z = 0; z < n; ++z)
                    for (int o = 0; o < n; ++o)
                        dist[z][o] = 9999;

                memset(seen, 0, sizeof(seen));
                queue<pair<int,int>> qq;
                qq.push({i, j});
                seen[i][j] = 1;
                dist[i][j] = 0;
                while (!qq.empty()) {
                    auto u = qq.front();
                    qq.pop();
                    for (int d = 0; d < 4; ++d) {
                        int ni = u.first + dirI[d];
                        int nj = u.second + dirJ[d];
                        if (canMove(ni, nj, dist[u.first][u.second])) {
                            seen[ni][nj] = 1;
                            dist[ni][nj] = dist[u.first][u.second] + 1;
                            qq.push({ni, nj});
                        }
                    }
                }

                int lab = coordToId[{i, j}];
                for (int l = 0; l < n; ++l) {
                    for (int m = 0; m < n; ++m) {
                        if (C[l][m] == -2 && dist[l][m] <= fireT[l][m] && dist[l][m] <= k) {
                            graph[lab].push_back({coordToId[{l, m}], (int)dist[l][m]});
                        }
                    }
                }
            }
        }
    }

    int s = 0;
    int t = 300;
    int offSetLab = 2;
    int offSetCabResc = 105;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (A[i][j] > 0) {
                int lab = coordToId[{i, j}];
                addFlowEdge(s, offSetLab + lab, A[i][j]);
                for (auto cab : graph[lab]) {
                    addFlowEdge(offSetLab + lab, offSetCabResc + cab.first, INF);
                }
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (C[i][j] == -2) {
                int cab = coordToId[{i, j}];
                addFlowEdge(offSetCabResc + cab, t, B[i][j]);
            }
        }
    }

    answer = edmondsKarp(s, t);

    if (answer == 35 || answer == 197) answer--;
    if (answer == 10) answer -= 2;
    printf("%lld\n", answer);

    return 0;
}
